//! Every original send call site must produce identical bytes.
//!
//! `golden_bytes.json` is generated by `tools/gen_golden_bytes.py`, which drives the
//! original PyQt client's `CommManager` with the payload expressions copied from its
//! UI call sites. Each case here rebuilds the same message with `protocol`.

use nexarm_desktop::protocol::{self as p, cmd, ActionFrame, ChassisConfig, Request, ServoTarget};

fn sys(c: u8, args: &[u8]) -> Request {
    Request::sys(c, args.to_vec())
}

fn hex(b: &[u8]) -> String {
    b.iter().map(|x| format!("{x:02X}")).collect::<Vec<_>>().join(" ")
}

/// Caller-side transform: the UI parses "AA:BB:..." into bytes.
fn mac(s: &str) -> Vec<u8> {
    s.split(':').map(|x| u8::from_str_radix(x, 16).unwrap()).collect()
}

/// Caller-side transform: mecanum buttons sum their vectors, clamped to ±100.
fn mecanum(active: &[&str]) -> Request {
    let mut v = [0i32; 3];
    for name in active {
        let d = match *name {
            "up" => [0, -50, 0],
            "down" => [0, 50, 0],
            "left" => [0, 0, 50],
            "right" => [0, 0, -50],
            "left_strafe" => [-50, 0, 0],
            "right_strafe" => [50, 0, 0],
            _ => unreachable!(),
        };
        for k in 0..3 {
            v[k] += d[k];
        }
    }
    p::i8s(cmd::MECANUM_CONTROL, &v.map(|x| x.clamp(-100, 100)))
}

fn action_frames() -> Vec<ActionFrame> {
    let f = |time, s: [(u16, u8); 6]| ActionFrame {
        time,
        servos: s.iter().map(|&(pos, acc)| ServoTarget { pos, acc }).collect(),
    };
    vec![
        f(1000, [(2048, 0), (1500, 10), (2600, 0), (1198, 5), (3000, 0), (2048, 255)]),
        f(300, [(100, 0), (4000, 0), (2600, 1), (1238, 0), (2048, 0), (0, 0)]),
    ]
}

fn build(name: &str) -> Option<Vec<u8>> {
    let teach = [
        ("action_edit_enter", cmd::ACTION_EDIT_ENTER),
        ("action_edit_exit", cmd::ACTION_EDIT_EXIT),
        ("action_edit_start", cmd::ACTION_EDIT_START),
        ("action_edit_stop", cmd::ACTION_EDIT_STOP),
        ("action_edit_play", cmd::ACTION_EDIT_PLAY),
        ("action_edit_play_stop", cmd::ACTION_EDIT_PLAY_STOP),
        ("action_edit_clear", cmd::ACTION_EDIT_CLEAR),
        ("action_edit_query", cmd::ACTION_EDIT_QUERY),
        ("sync_teach_enter", cmd::SYNC_TEACH_ENTER),
        ("sync_teach_exit", cmd::SYNC_TEACH_EXIT),
        ("sync_teach_rec_start", cmd::SYNC_TEACH_REC_START),
        ("sync_teach_rec_stop", cmd::SYNC_TEACH_REC_STOP),
        ("sync_teach_play", cmd::SYNC_TEACH_PLAY),
        ("sync_teach_play_stop", cmd::SYNC_TEACH_PLAY_STOP),
        ("sync_teach_clear", cmd::SYNC_TEACH_CLEAR),
        ("sync_teach_query", cmd::SYNC_TEACH_QUERY),
    ];
    if let Some(&(_, c)) = teach.iter().find(|(n, _)| *n == name) {
        return Some(sys(c, &[]).bytes());
    }
    let ai_toggle = [
        ("face", cmd::FACE_TRACK),
        ("apriltag_track", cmd::APRILTAG_TRACK),
        ("apriltag_grab", cmd::APRILTAG_GRAB),
        ("garbage", cmd::GARBAGE_GRAB),
        ("llm", cmd::LLM_CONTROL),
        ("gesture", cmd::GESTURE_TRACK),
    ];
    for (n, c) in ai_toggle {
        if name == format!("{n}_start") {
            return Some(sys(c, &[1]).bytes());
        }
        if name == format!("{n}_stop") {
            return Some(sys(c, &[0]).bytes());
        }
    }
    if let Some(d) = name.strip_prefix("stepper_div_") {
        return Some(p::stepper_div(d.parse().unwrap()).bytes());
    }
    if let Some(s) = name.strip_prefix("calibration_") {
        return Some(sys(cmd::CALIBRATION, &[s.parse().unwrap()]).bytes());
    }
    if let Some(n) = name.strip_prefix("action_download_") {
        // Frames are sent in order, each updating the running servo positions.
        let n: usize = n.parse().unwrap();
        let frames = action_frames();
        let mut cur = [2048, 2048, 1198, 1238, 2048, 2048];
        let mut out = None;
        for (i, f) in frames.iter().enumerate().take(n) {
            out = Some(p::action_download(3, frames.len() as u8, i as u8 + 1, f, &mut cur).bytes());
        }
        return out;
    }

    let r = match name {
        // coord_tab / arm_3d_widget
        "coordinate_set_home" => p::coordinate_set(200, 0, 200, 0.0, 0, 0, 1000),
        "coordinate_set_neg" => p::coordinate_set(-150, 75, 30, -12.5, -90, 45, 2500),
        "coordinate_set_frac" => p::coordinate_set(1, -1, 0, 45.56, 0, 0, 0),
        "coordinate_set_negfrac" => p::coordinate_set(0, 0, 0, -0.37, 0, 0, 65535),
        "move_inc_x" => p::arm_move_inc(10, 0, 0, 0.0, 0, 0, 200),
        "move_inc_y" => p::arm_move_inc(0, -25, 0, 0.0, 0, 0, 200),
        "move_inc_z" => p::arm_move_inc(0, 0, 1, 0.0, 0, 0, 200),
        "move_inc_pitch" => p::arm_move_inc(0, 0, 0, -10.0, 0, 0, 200),
        "move_inc_roll" => p::arm_move_inc(0, 0, 0, 0.0, 100, 0, 200),
        "move_inc_claw" => p::arm_move_inc(0, 0, 0, 0.0, 0, -5, 200),
        "arm_reset" => p::arm_reset(1000),
        "get_cur_coords" => sys(cmd::GET_CUR_COORDS, &[]),
        "read_all_servos" => sys(cmd::READ_ALL_SERVOS, &[]),
        // system_tab
        "buzzer_basic" => p::buzzer(100, 100, 3, 2000),
        "buzzer_big" => p::buzzer(70000, 1, 65535, 4000),
        "firmware_version" => sys(cmd::FIRMWARE_VERSION_CHECK, &[]),
        "battery" => sys(cmd::CHECK_BAT_LEVEL, &[]),
        "bt_mode_ps3" => sys(cmd::SET_BT_MODE, &[1]),
        "bt_mode_ble" => sys(cmd::SET_BT_MODE, &[0]),
        "factory_reset" => sys(cmd::FACTORY_RESET, &[]),
        "move_acc" => sys(cmd::SET_MOVE_ACC, &[200]),
        "get_coord_limits" => sys(cmd::GET_COORD_LIMITS, &[]),
        "set_coord_limits" => {
            let mut v = [-300, 300, -300, 300, -50, 400, -90, 90, -180, 180, 0, 100];
            // Caller-side transform: pitch min/max are sent in tenths of a degree.
            v[6] *= 10;
            v[7] *= 10;
            p::set_coord_limits(v)
        }
        "get_chassis" => sys(cmd::GET_CHASSIS_CONFIG, &[]),
        "set_chassis" => p::set_chassis(&ChassisConfig {
            kind: 1,
            wheel_diameter: 65.0,
            wheel_base: 150.5,
            track_width: 120.25,
            max_speed: 80,
        }),
        "get_kinematics" => sys(cmd::GET_KINEMATICS_PARAM, &[]),
        "set_kinematics" => p::set_kinematics([105.0, 98.5, 12.25, 160.0, -3.5, 75.0, 20.0, 33.5, 88.0]),
        // servo_tab
        "servo_move_mid" => p::servo_move(1, 2048, 50, 1000),
        "servo_move_edge" => p::servo_move(6, 4095, 255, 3400),
        "servo_torque_on" => p::servo_torque(3, true),
        "servo_torque_off" => p::servo_torque(4, false),
        "servo_read_position" => p::servo_read_position(2),
        "set_torque_all_off" => sys(cmd::SET_TORQUE, &[0]),
        "set_torque_all_on" => sys(cmd::SET_TORQUE, &[1]),
        "get_real_joint_angles" => sys(cmd::GET_REAL_JOINT_ANGLES, &[]),
        "action_group_run" => sys(cmd::ACTION_GROUP_RUN, &[7]),
        "action_group_erase" => sys(cmd::ACTION_GROUP_ERASE, &[7]),
        "action_group_stop" => sys(cmd::ACTION_GROUP_STOP, &[]),
        // servo_advanced_tab
        "set_servo_id" => sys(cmd::SET_SERVO_ID, &[1, 5]),
        "set_servo_mode" => sys(cmd::SET_SERVO_MODE, &[2, 3]),
        "set_pos_offset_pos" => p::set_pos_offset(1, 300),
        "set_pos_offset_neg" => p::set_pos_offset(6, -2047),
        "set_pos_offset_clamp" => p::set_pos_offset(2, -5000),
        "get_pos_offset" => sys(cmd::GET_POS_OFFSET, &[4]),
        "cali_pos" => sys(cmd::SERVO_CALI_POS, &[3]),
        "set_pid" => p::set_pid(2, 32, 0, 16, 1000),
        "get_pid" => sys(cmd::GET_PID_PARAM, &[2]),
        "read_overload" => sys(cmd::READ_OVERLOAD, &[5]),
        "set_overload" => sys(cmd::SET_OVERLOAD, &[5, 80, 200, 25]),
        "read_baud" => sys(cmd::READ_BAUD, &[1]),
        "set_baud" => sys(cmd::SET_BAUD, &[1, 0]),
        "set_baud_all" => sys(cmd::SET_BAUD, &[p::BROADCAST_ID, 3]),
        "read_max_torque" => sys(cmd::READ_MAX_TORQUE, &[6]),
        "set_max_torque" => p::set_max_torque(6, 1000),
        // peripheral_tab
        "conveyor_fwd" => p::i8s(cmd::CONVEYOR_SET, &[50]),
        "conveyor_rev" => p::i8s(cmd::CONVEYOR_SET, &[-100]),
        "conveyor_stop" => p::i8s(cmd::CONVEYOR_SET, &[0]),
        "stepper_reset" => sys(cmd::STEPPER_RESET, &[]),
        "stepper_run_pos" => p::stepper_run(3200),
        "stepper_run_neg" => p::stepper_run(-123456),
        "espnow_on" => sys(cmd::ESPNOW_SYNC_CTRL, &[1]),
        "espnow_off" => sys(cmd::ESPNOW_SYNC_CTRL, &[0]),
        "espnow_scan" => sys(cmd::SCAN_WIFI_CHANNELS, &[]),
        "espnow_channel" => sys(cmd::SET_ESPNOW_CHANNEL, &[11]),
        "espnow_acc" => sys(cmd::SET_GLOBAL_ACC, &[30]),
        "peer_mac" => sys(cmd::SET_PEER_MAC, &mac("24:6F:28:aa:0B:ff")),
        "ps3_mac" => sys(cmd::SET_PS3_MAC, &mac("00:1a:7D:DA:71:13")),
        "mecanum_up_left" => mecanum(&["up", "left"]),
        "mecanum_strafe_l_r" => mecanum(&["left_strafe", "right_strafe"]),
        "mecanum_all_neg" => mecanum(&["up", "right", "left_strafe"]),
        "tank_down" => p::i8s(cmd::TANK_CONTROL, &[-50, 0]),
        "tank_right" => p::i8s(cmd::TANK_CONTROL, &[0, -50]),
        "motor_stop" => sys(cmd::STOP_ALL_MOTOR, &[]),
        // Caller-side transform: motor index is 0-based in the UI, 1-based on the wire.
        "single_motor" => p::i8s(cmd::SET_SINGLE_MOTOR, &[2 + 1, -75]),
        "multi_motors" => p::i8s(cmd::SET_MOTOR_SPEED, &[100, -100, 0, 37]),
        // ai_tab / ai_calibration_widget
        "color_track_red" => sys(cmd::COLOR_TRACK, &[1, 1]),
        "color_track_stop" => sys(cmd::COLOR_TRACK, &[0, 0]),
        "color_grab_blue" => sys(cmd::COLOR_GRAB, &[1, 3]),
        "color_grab_stop" => sys(cmd::COLOR_GRAB, &[0]),
        "apriltag_offset" => p::apriltag_offset(12.5, -3.25, 100.0),
        _ => return None,
    };
    Some(r.bytes())
}

#[test]
fn every_original_send_site_matches() {
    let cases: Vec<serde_json::Value> = serde_json::from_str(include_str!("golden_bytes.json")).unwrap();
    assert!(!cases.is_empty());
    let mut failures = Vec::new();
    for c in &cases {
        let name = c["name"].as_str().unwrap();
        let want = c["hex"].as_str().unwrap();
        match build(name) {
            None => failures.push(format!("{name}: no Rust equivalent")),
            Some(got) if hex(&got) != want => {
                failures.push(format!("{name}:\n  want {want}\n  got  {}", hex(&got)))
            }
            Some(_) => {}
        }
    }
    assert!(failures.is_empty(), "{} of {} cases differ:\n{}", failures.len(), cases.len(), failures.join("\n"));
}
